// swift-tools-version: 6.0
import PackageDescription

/// SwiftPM manifest for command-line builds and tests of the non-UI core.
///
/// The shipping app is built from `ScreenForge.xcodeproj` (generated by XcodeGen),
/// which compiles the SwiftUI layer and the Metal shaders. This package exists so
/// the model, analysis, capture, and media cores can be built and tested with only
/// the Command Line Tools installed.
let package = Package(
    name: "ScreenForge",
    platforms: [.macOS(.v14)],
    products: [
        .library(name: "ScreenForgeCore", targets: ["ScreenForgeCore"])
    ],
    targets: [
        .target(
            name: "ScreenForgeCore",
            path: "ScreenForge",
            exclude: [
                // App shell and SwiftUI layers need Xcode (SwiftUI macros).
                "App/AppState.swift",
                "App/ScreenForgeApp.swift",
                "App/Info.plist",
                "App/ScreenForge.entitlements",
                "UI",
                "Editor",
                "Resources",
                "Media/Shaders.metal"
            ],
            swiftSettings: [
                .swiftLanguageMode(.v6),
                .unsafeFlags(["-strict-concurrency=complete"])
            ]
        ),
        .testTarget(
            name: "ScreenForgeTests",
            dependencies: ["ScreenForgeCore"],
            path: "Tests",
            swiftSettings: [
                .swiftLanguageMode(.v6),
                .unsafeFlags(["-strict-concurrency=complete"])
            ]
        )
    ]
)
